import type { Metadata } from "next";

export const SITE_NAME = "Popsy Adonis";
export const HOME_TITLE = "Popsy Adonis | Nigerian Entertainment, Artists, Events & PA FLUX";
export const HOME_DESCRIPTION =
  "A high-end Nigerian entertainment and lifestyle platform for trends, artist portfolios, events, promotions, ticketing, and PA FLUX clothing.";

/** The branded card generated by src/app/opengraph-image.tsx. */
export const DEFAULT_OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: SITE_NAME };

type OgImage = { url: string; width?: number; height?: number; alt?: string };

/**
 * Link-preview tags for one page. Each page needs its own: a page that sets none inherits the
 * homepage's title and link, so sharing it shows the homepage instead.
 */
export function openGraphFor({
  title,
  description,
  path,
  image = DEFAULT_OG_IMAGE,
}: {
  title: string;
  description: string;
  path: string;
  image?: OgImage;
}): NonNullable<Metadata["openGraph"]> {
  return {
    type: "website",
    siteName: SITE_NAME,
    locale: "en_NG",
    url: path,
    title,
    description,
    images: [image],
  };
}
